def weak_headers(headers):
    h = {name.lower(): value.strip().lower() for name, value in headers.items()}
    weak = []
    hsts = h.get("strict-transport-security")
    max_age = 0
    if hsts:
        for part in hsts.split(";"):
            part = part.strip()
            if part.startswith("max-age="):
                value = part[len("max-age="):]
                max_age = int(value) if value.isdigit() else 0
    if max_age < 31536000:
        weak.append("strict-transport-security")
    if h.get("x-content-type-options") != "nosniff":
        weak.append("x-content-type-options")
    if h.get("x-frame-options") not in ("deny", "sameorigin"):
        weak.append("x-frame-options")
    return weak

